RSpec.describe Timekeeping::LocalOwner do
  # "A credential nested in an entry body answers credential_in_body and nothing is stored"
  it "a body holding the service token two levels deep answers credential_in_body and stores no row anywhere" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation.to_s
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    held_token = "local-owner-held-service-token-#{SecureRandom.hex(16)}"
    previous = ENV.fetch("TIMEKEEPING_SERVICE_TOKEN", nil)
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = held_token

    begin
      outcome = described_class.call(
        operation: :create, company_id: company.id, generation:,
        actor: described_class::Actor.user(user_id: user.id, role: "employee"),
        params: {
          "idempotency_key" => "leaky",
          "body" => { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 10.0,
                      "note" => "x", "source" => "manual",
                      "source_metadata" => { "headers" => { "authorization" => held_token } } }
        }
      )
    ensure
      ENV["TIMEKEEPING_SERVICE_TOKEN"] = previous
    end

    expect(outcome.body.with_indifferent_access[:reason]).to eq("credential_in_body")
    expect(outcome.body.to_json).not_to include(held_token)
    expect(count.call("entries")).to eq(0)
    expect(count.call("entry_audits")).to eq(0)
    expect(count.call("entry_outbox_items")).to eq(0)
    expect(count.call("idempotency_records")).to eq(0)
  end
end


RSpec.describe Timekeeping::LocalOwner do
  # "`locked` is true when any reservation row, provisional or committed, exists for the entry in the same company."
  it "the outbox payload of an update reads locked from reservations, not from entries.locked" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation.to_s
    company = create(:company)
    owner = create(:user)
    create(:employment, company:, user: owner)
    owner.add_role("owner", company)
    project = create(:project, client: create(:client, company:))
    unbilled = TimesheetEntry.bill_statuses.keys.reject { |status| status == "billed" }.first
    reserved = Timekeeping::LocalEntry.create!(company_id: company.id, user_id: owner.id, project_id: project.id,
                                               work_date: Date.current, duration: 1.0, bill_status: unbilled, locked: false)
    flagged_only = Timekeeping::LocalEntry.create!(company_id: company.id, user_id: owner.id, project_id: project.id,
                                                   work_date: Date.current, duration: 1.0, bill_status: unbilled, locked: true)
    ActiveRecord::Base.connection.execute(ActiveRecord::Base.sanitize_sql_array([
      "INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at) " \
      "VALUES (?, ?, ?, ?, 'provisional', 'active', now())",
      company.id, reserved.id, 9_001, SecureRandom.uuid
    ]))
    update = lambda do |entry, key|
      described_class.call(
        operation: :update, company_id: company.id, generation:,
        actor: described_class::Actor.user(user_id: owner.id, role: "owner"),
        params: { "idempotency_key" => key, "entry_id" => entry.id, "body" => { "note" => "touched" } }
      )
    end

    expect(update.call(reserved, "lock-a").status).to eq(200)
    expect(update.call(flagged_only, "lock-b").status).to eq(200)

    expect(Timekeeping::LocalOutboxEntry.find_by!(company_id: company.id, entry_id: reserved.id).payload["locked"]).to be(true)
    expect(Timekeeping::LocalOutboxEntry.find_by!(company_id: company.id, entry_id: flagged_only.id).payload["locked"]).to be(false)
  end
end
